WITH item_returns AS ( SELECT i.i_item_sk, i.i_product_name, i.i_current_price, i.i_wholesale_cost, SUM(wr.wr_return_amt) AS total_return_amount, COUNT(*) AS return_cnt FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk GROUP BY i.i_item_sk, i.i_product_name, i.i_current_price, i.i_wholesale_cost ), item_inventory AS ( SELECT inv.inv_item_sk, w.w_warehouse_name, inv.inv_quantity_on_hand, ROW_NUMBER() OVER (PARTITION BY inv.inv_item_sk ORDER BY inv.inv_quantity_on_hand DESC) AS wh_rank FROM inventory inv JOIN warehouse w ON inv.inv_warehouse_sk = w.w_warehouse_sk ) SELECT * FROM ( SELECT ir.i_item_sk, ir.i_product_name, ir.total_return_amount, ir.return_cnt, ir.i_current_price, ir.i_wholesale_cost, CASE WHEN (ir.i_current_price - ir.i_wholesale_cost) / ir.i_current_price > 0.5 THEN 'High Margin' WHEN (ir.i_current_price - ir.i_wholesale_cost) / ir.i_current_price > 0.2 THEN 'Medium Margin' ELSE 'Low Margin' END AS margin_category, ii.w_warehouse_name, ii.inv_quantity_on_hand, ii.wh_rank, RANK() OVER (ORDER BY ir.total_return_amount DESC) AS rnk FROM item_returns ir JOIN item_inventory ii ON ir.i_item_sk = ii.inv_item_sk WHERE ii.wh_rank = 1 ) t WHERE t.rnk <= 5 ORDER BY t.rnk
